import modlix, json

# First create the vclone app (security + UI)
try:
    sec = modlix.post('/api/security/applications', {
        'appCode': 'vclone',
        'appName': 'vclone',
        'appType': 'SITE',
        'appAccessType': 'OWN',
    })
    print("Security app created:", sec)
except Exception as e:
    print("Security app error (may exist):", e)

try:
    ui = modlix.post('/api/ui/applications', {
        'appCode': 'vclone',
        'name': 'vclone',
        'applicationType': 'SITE',
        'properties': {'defaultPage': 'home'},
    })
    print("UI app created:", ui)
except Exception as e:
    print("UI app error (may exist):", e)

# Now create the home page
try:
    page = modlix.post('/api/ui/pages', {
        'appCode': 'vclone',
        'name': 'home',
        'permission': 'Authorities.ANYTIME',
    })
    print("Page created:", page)
except Exception as e:
    print("Page error (may exist):", e)

