import modlix, json

u = modlix.uuid

# Asset URLs from harvest
LOGO_URL = "http://localhost:8080/api/files/static/file/SYSTEM/vclone/global/clone/img_9f15332e27.avif"
HERO_APP_IMG = "http://localhost:8080/api/files/static/file/SYSTEM/vclone/global/clone/img_2ec782060b.png"
HERO_WIDE_IMG = "http://localhost:8080/api/files/static/file/SYSTEM/vclone/global/clone/img_383d438f29.png"

def sp(styles_all, styles_extra=None):
    """Create styleProperties with one UUID key"""
    key = u()
    d = {"resolutions": {"ALL": {k: {"value": v} for k, v in styles_all.items()}}}
    if styles_extra:
        for res, props in styles_extra.items():
            d["resolutions"][res] = {k: {"value": v} for k, v in props.items()}
    return {key: d}

def text_comp(key, text_val, styles):
    return {
        "key": key,
        "name": key,
        "type": "Text",
        "styleProperties": sp(styles),
        "properties": {
            "text": {"value": text_val}
        },
        "override": False,
        "children": {}
    }

def grid_comp(key, name, styles, children_keys=None):
    return {
        "key": key,
        "name": name,
        "type": "Grid",
        "styleProperties": sp(styles),
        "properties": {},
        "override": False,
        "children": {k: True for k in (children_keys or [])}
    }

def link_comp(key, name, text_val, href, styles, text_styles):
    """A grid that acts as a nav link"""
    tk = u()
    comp = {
        "key": key,
        "name": name,
        "type": "Grid",
        "styleProperties": sp(styles),
        "properties": {
            "linkPath": {"value": href},
        },
        "override": False,
        "children": {tk: True}
    }
    text = text_comp(tk, text_val, text_styles)
    return comp, text

def img_comp(key, name, src, styles):
    return {
        "key": key,
        "name": name,
        "type": "Image",
        "styleProperties": sp(styles),
        "properties": {
            "src": {"value": src},
        },
        "override": False,
        "children": {}
    }

