LOGO_URL = "http://localhost:8080/api/files/static/file/SYSTEM/vclone/global/clone/img_9f15332e27.avif"

def sp(styles):
    key = u()
    return {key: {"resolutions": {"ALL": {k: {"value": v} for k, v in styles.items()}}}}

def text_comp(key, text_val, styles):
    return {
        "key": key, "name": key, "type": "Text",
        "styleProperties": sp(styles),
        "properties": {"text": {"value": text_val}},
        "override": False, "children": {}
    }

def grid_comp(key, name, styles, children_keys=None):
    return {
        "key": key, "name": name, "type": "Grid",
        "styleProperties": sp(styles),
        "properties": {}, "override": False,
        "children": {k: True for k in (children_keys or [])}
    }

def img_comp(key, name, src, styles):
    return {
        "key": key, "name": name, "type": "Image",
        "styleProperties": sp(styles),
        "properties": {"src": {"value": src}},
        "override": False, "children": {}
    }

